{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In a human study, ingestion of 23.6 mg lycopene in tomato paste resulted in only 0.17% systemic availability, showing that a large, highly lipophilic polyisoprenoid can have extremely low oral bioavailability; despite low transferability, the structural analogy to the query's long isoprenoid chain supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A 38-mg lycopene capsule yielded approximately 2.6% bioavailability in humans, another affirmative low-F measurement for a structurally related isoprenoid, reinforcing that very large lipophilic isoprenoids often fail to reach 20% oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "A high-transfer 13C-lycopene study reported 24.5% bioavailability for cis-lycopene, suggesting that some highly lipophilic isoprenoids can exceed 20%; however, the query is substantially larger (863 Da) and this evidence is not sufficient to override the low prior and the more structurally aligned low-F data.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a highly lipophilic retinoid with a polyene chain, has about 40% absolute bioavailability in healthy volunteers, indicating that poor aqueous solubility alone does not preclude F>=20%; but its much lower molecular weight (354 Da) and different polar head group limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is an extremely large, highly lipophilic ubiquinone (CoQ10) with no ionizable groups and 31 rotatable bonds. Although high-transfer analogues such as etretinate and cis-lycopene show F>=20%, their lower molecular weights and different polar head groups limit direct transfer. The most structurally similar low-transfer lycopene data affirmatively show very low systemic availability (0.17-2.6%), and the physicochemical prior strongly predicts poor absorption. Therefore, F<20% is more likely.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the query molecule (CoQ10) are provided.",
    "The low-transfer lycopene data come from food-matrix studies, which may not reflect pharmaceutical formulations relevant to the query.",
    "The high-transfer analogues are smaller and less lipophilic than the query, leaving uncertainty about extrapolation to a 863 Da, logP 17.85 molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

